// Format the weekly digest. Phase 2 build-order item 8 ("weekly
// unanswered-questions digest for the product owner") plus basic funnel counts.
const LABELS = {
  quote_submitted: 'Quotes submitted',
  partner_submitted: 'Partner applications submitted',
  unanswered: 'Questions the bot could not answer',
  quote_handoff: 'Quote-flow handoffs to a human',
  partner_handoff: 'Partner-flow handoffs to a human',
  tracking_handoff: 'Tracking handoffs to a human',
  quote_not_priceable: 'Quotes needing manual pricing',
  human_requested: 'Direct "talk to us" requests',
  human_requested_midflow: 'Mid-flow "talk to us" requests'
};
const counts = $('Fetch Weekly Counts').all().map(i => i.json).filter(r => r && r.event_key);
const questions = $input.all().map(i => i.json).filter(r => r && r.question);

const lines = ['\ud83d\udcca the AI service weekly summary (last 7 days)', ''];
if (counts.length === 0) {
  lines.push('No logged activity this week.');
} else {
  for (const c of counts) {
    lines.push('\u2022 ' + (LABELS[c.event_key] || c.event_key) + ': ' + c.n);
  }
}
lines.push('');
if (questions.length > 0) {
  lines.push('\u2753 Top unanswered questions (for the knowledge base):');
  questions.slice(0, 15).forEach((q, i) => {
    lines.push((i + 1) + '. ' + q.question + (Number(q.n) > 1 ? '  (\u00d7' + q.n + ')' : ''));
  });
} else {
  lines.push('\u2705 No unanswered questions this week.');
}
return { json: { digest: lines.join('\n') } };
